        "history": "تأسس قسم هندسة الكهرباء والطاقة في عام 1977 تحت اسم 'الهندسة الكهربائية العامة'، حيث انفصل عن قسم 'العلوم الهندسية العامة' تحت إدارة م. ت. توردييف. ومنذ عام 1978، بدأت الدراسة المسائية في تخصص 'إمداد الطاقة للمؤسسات الصناعية والمدن والزراعة'، وتلاها التعليم النهاري في 'هندسة الطاقة' عام 1985، وتأسست دراسات الماجستير عام 2000.\nتولى رئاسة القسم كل من م. ت. توردييف (1977-1985، 1994-2005)، أ. م. عبد الله ييف (1985-1994)، ن. ن. سادولاييف (2005-2011)، م. إ. محمودوف (2011-2018)، وإ. إ. خافيزوف (2018-2019).\nوفي عام 2019، تم تأسيس ثلاثة أقسام منفصلة: 'الميكانيكا الكهربائية والتقنيات'، و'الطاقة'، و'تدقيق الطاقة'.\nونتيجة للتغييرات في الهيكل الداخلي للجامعة في العام الدراسي 2024-2025، تم دمج الأقسام الثلاثة في قسم واحد باسم 'قسم هندسة الكهرباء والطاقة'. وتولى ن. ن. ميرزاييف إدارة القسم في العام 2024-2025، ومنذ بداية العام الدراسي 2025-2026، يتولى الأستاذ المشارك لطيفوف سعيد مراد تويغونوفيتش رئاسة القسم.",
        "research": "يشارك في العمل البحثي بالقسم دكتوران في العلوم، و3 حاصلين على الدكتوراه، و6 محاضرين أوائل، بالإضافة إلى باحثين مستقلين وطلاب ماجستير. تم الحصول على منحة حكومية بقيمة 500 مليون سوم لتطوير منشأة طاقة رياح تعمل بكفاءة في الظروف المناخية لأوزبكستان. كما تم تنفيذ عقود تجارية مع 9 مؤسسات صناعية بقيمة 92 مليون سوم لتنفيذ عمليات تدقيق الطاقة.",
